/**
 * Room reflection probe — code-split chunk.
 *
 * A lighting-profile world is usually an INTERIOR authored in a DCC whose
 * viewport renders real reflections (Eevee SSR / ray tracing): its windows,
 * mirrors, and chrome expect to reflect the ROOM, but the shell's only
 * environment is the flat neutral IBL — glass reads dead. This chunk renders
 * a ONE-SHOT cubemap probe from the world's interior center and assigns it as
 * the reflection texture of exactly the materials that visibly mirror:
 * near-smooth (roughness < 0.3) or transparent (alpha < 0.6) PBR materials.
 * Everything else keeps the neutral IBL (a raw, unfiltered probe cube looks
 * wrong on rough surfaces — prefiltering is the future upgrade).
 *
 * Dynamically imported ONLY when a profile world delivers lights (the
 * main bundle never pays for ReflectionProbe/RenderTargetTexture).
 */
import { ReflectionProbe } from '@babylonjs/core/Probes/reflectionProbe';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Scene } from '@babylonjs/core/scene';

/** Roughness below this reads as a mirror-ish surface worth probe reflections. */
export const PROBE_ROUGHNESS_MAX = 0.3;
/** Alpha below this reads as glazing (windows) worth probe reflections. */
export const PROBE_ALPHA_MAX = 0.6;
/** Probe cube face size — static one-shot render, so quality over speed. */
export const PROBE_SIZE = 512;
/** Probe eye height above the content's floor (a standing viewer's view). */
const PROBE_EYE_M = 1.6;

export interface RoomReflectionProbeHandle {
  /** Names of the materials that received the probe (observability/tests). */
  readonly reflectiveMaterialNames: readonly string[];
  dispose(): void;
}

/** The code-split module shape — mirrors the panorama/sky/
 * equirect chunk loader seams in applyEnvironment.ts. */
export interface RoomReflectionProbeModule {
  createRoomReflectionProbe: typeof createRoomReflectionProbe;
}

interface ReflectiveMaterial {
  name: string;
  alpha: number;
  roughness?: number | null;
  metallic?: number | null;
  reflectionTexture?: unknown;
  environmentIntensity?: number;
  getClassName(): string;
}

/** Metallic at/above this with moderate roughness reads as chrome/mirror. */
export const PROBE_METALLIC_MIN = 0.6;
/**
 * Reflection boost for TRANSPARENT glazing (windows). Physically, uncoated
 * glass reflects ~4% head-on (Fresnel) — real but nearly invisible over a
 * dark backdrop, while DCC viewport SSR reads much stronger to the eye. The
 * boost approximates coated architectural glazing so windows visibly mirror
 * the room, as the author's DCC viewport shows them.
 */
export const GLASS_REFLECTION_BOOST = 3;

/**
 * Build the probe at the meshes' bounds center (floor + eye height) and wire
 * it into every mirror-ish PBR material. Returns a disposer; safe on an empty
 * mesh list (no probe, no-op dispose).
 */
export function createRoomReflectionProbe(
  scene: Scene,
  meshes: readonly AbstractMesh[],
): RoomReflectionProbeHandle {
  const renderable = meshes.filter((m) => !m.isDisposed() && m.getTotalVertices() > 0);
  if (renderable.length === 0) {
    return { reflectiveMaterialNames: [], dispose: () => undefined };
  }

  let min: Vector3 | null = null;
  let max: Vector3 | null = null;
  for (const mesh of renderable) {
    mesh.computeWorldMatrix(true);
    const box = mesh.getBoundingInfo().boundingBox;
    min = min === null ? box.minimumWorld.clone() : Vector3.Minimize(min, box.minimumWorld);
    max = max === null ? box.maximumWorld.clone() : Vector3.Maximize(max, box.maximumWorld);
  }
  const center = min!.add(max!).scale(0.5);
  const position = new Vector3(center.x, min!.y + PROBE_EYE_M, center.z);

  // Which materials will receive the probe — decided BEFORE the render list,
  // because a mesh may never both feed the probe and sample it: WebGL refuses
  // to draw a framebuffer that is also a bound texture ("feedback loop formed
  // between Framebuffer and active Texture") and the frame can come back
  // BLACK. A mirror reflecting itself is meaningless anyway.
  const reflective = new Set<ReflectiveMaterial>();
  for (const material of scene.materials as unknown as ReflectiveMaterial[]) {
    if (material.getClassName() !== 'PBRMaterial') continue;
    const roughness = material.roughness ?? 1;
    const glassy = material.alpha < PROBE_ALPHA_MAX;
    const chromey = (material.metallic ?? 0) >= PROBE_METALLIC_MIN && roughness < 0.7;
    if (roughness < PROBE_ROUGHNESS_MAX || glassy || chromey) reflective.add(material);
  }

  const probe = new ReflectionProbe('roomReflectionProbe', PROBE_SIZE, scene);
  probe.position.copyFrom(position);
  for (const mesh of renderable) {
    const material = mesh.material as unknown as ReflectiveMaterial | null;
    if (material !== null && reflective.has(material)) continue;
    probe.renderList!.push(mesh);
  }
  // Static world → render the six faces once, then it costs nothing per
  // frame. Numeric literal = RenderTargetTexture.REFRESHRATE_RENDER_ONCE —
  // importing the class here would trip the shader-import manifest lint
  // (Materials/Textures specifier) for one constant.
  probe.refreshRate = 0;
  // TIMING: the first one-shot fires on the next render
  // pass — DURING load, while PBR shaders still compile and textures upload —
  // capturing a black room (an invisible reflection). Re-arm the one-shot
  // when the scene reports ready, and once more after a beat for streamed
  // textures; each re-arm is one 6-face render, then static again.
  let lateRearm: ReturnType<typeof setTimeout> | undefined;
  scene.executeWhenReady(() => {
    probe.cubeTexture.resetRefreshCounter();
    lateRearm = setTimeout(() => {
      if (!scene.isDisposed) probe.cubeTexture.resetRefreshCounter();
    }, 3000);
  });

  const touched: Array<{
    material: ReflectiveMaterial;
    prior: unknown;
    priorIntensity: number | undefined;
  }> = [];
  for (const material of reflective) {
    touched.push({ material, prior: material.reflectionTexture, priorIntensity: material.environmentIntensity });
    material.reflectionTexture = probe.cubeTexture;
    if (material.alpha < PROBE_ALPHA_MAX) {
      material.environmentIntensity = (material.environmentIntensity ?? 1) * GLASS_REFLECTION_BOOST;
    }
  }

  return {
    reflectiveMaterialNames: touched.map((t) => t.material.name),
    dispose(): void {
      if (lateRearm !== undefined) clearTimeout(lateRearm);
      for (const { material, prior, priorIntensity } of touched) {
        material.reflectionTexture = prior;
        if (priorIntensity !== undefined) material.environmentIntensity = priorIntensity;
      }
      probe.dispose();
    },
  };
}
